const iconArrow = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-5-5 5 5-5 5" fill="none" stroke="currentColor" stroke-width="1.6"/></svg>';
const heroArt = `<div class="hero-art"><svg viewBox="0 0 520 520" role="img" aria-label="Investigador, redactor y editor conectados en un equipo. Un resultado viaja entre los agentes."><circle class="orbit" cx="260" cy="260" r="216"/><circle class="orbit" cx="260" cy="260" r="164" stroke-dasharray="3 8"/><path class="connection" d="M130 135 390 220 230 400Z"/><circle class="packet" r="6"/><circle class="node" cx="130" cy="135" r="36"/><circle class="node-core" cx="130" cy="135" r="10"/><path d="M117 157q13-18 26 0" fill="none" stroke="#192535" stroke-width="2"/><circle class="node" cx="390" cy="220" r="36"/><path d="m379 229 4-13 15-15 9 9-15 15Z" fill="none" stroke="#192535" stroke-width="2"/><circle class="node" cx="230" cy="400" r="36"/><path d="m217 400 9 9 18-19" fill="none" stroke="#b74c27" stroke-width="3"/><text class="node-label" x="130" y="79" text-anchor="middle">Investigador</text><text class="node-sub" x="130" y="96" text-anchor="middle">Encuentra evidencia</text><text class="node-label" x="390" y="278" text-anchor="middle">Redactor</text><text class="node-sub" x="390" y="296" text-anchor="middle">Conecta las ideas</text><text class="node-label" x="230" y="463" text-anchor="middle">Editor</text><text class="node-sub" x="230" y="481" text-anchor="middle">Revisa el resultado</text><text x="247" y="246" font-size="17" fill="#596777" text-anchor="middle">Un objetivo</text><text x="247" y="270" font-size="17" text-anchor="middle" fill="#192535">compartido.</text></svg></div>`;
const slides = [{title:'De un modelo a un equipo',chapter:'La idea',render:()=>`<div class="split hero"><div class="hero-copy"><h1>CrewAI<span class="accent">.</span></h1><p class="hero-thesis">Una IA responde.<br>Un equipo <span class="accent">colabora.</span></p><p class="hero-description">Cómo coordinar agentes de inteligencia artificial para resolver una tarea juntos.</p><button class="start-button" data-next>Comenzar ${iconArrow}</button><p class="hero-meta">Introducción para TI · 20–30 minutos</p></div>${heroArt}</div>`}];
slides.push(...makeSlides());
let current=0;let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;let indexOpen=false;
const stage=document.getElementById('stage');const prev=document.getElementById('prev');const next=document.getElementById('next');
function navigate(n,updateHash=true){current=Math.min(Math.max(Number.isFinite(n)?Math.trunc(n):0,0),slides.length-1);const s=slides[current];stage.innerHTML=`<section class="slide" aria-label="${current+1}. ${s.title}">${s.render()}</section>`;stage.scrollTop=0;document.getElementById('counter').textContent=`${String(current+1).padStart(2,'0')} / ${String(slides.length).padStart(2,'0')}`;document.getElementById('progress').style.width=`${(current+1)/slides.length*100}%`;document.getElementById('chapter').textContent=s.chapter;prev.disabled=current===0;next.disabled=current===slides.length-1;document.title=`${current+1} · ${s.title} — CrewAI`;document.getElementById('announcement').textContent=`Diapositiva ${current+1} de ${slides.length}: ${s.title}`;if(updateHash)history.replaceState(null,'',`#${current+1}`);renderIndex();if(current===9)showExample(0);}
function renderIndex(){document.getElementById('index-items').innerHTML=slides.map((s,i)=>`<button class="index-item" data-slide="${i}" ${i===current?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${s.title}</button>`).join('');}
function toggleIndex(force){indexOpen=force??!indexOpen;document.getElementById('slide-index').hidden=!indexOpen;document.getElementById('index-toggle').setAttribute('aria-expanded',String(indexOpen));stage.inert=indexOpen;if(indexOpen)document.getElementById('close-index').focus();else document.getElementById('index-toggle').focus();}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,5000);}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Este navegador no ofrece pantalla completa. Usa el menú del navegador.');}catch{toast('No se pudo activar la pantalla completa. Prueba abrir la presentación en otra pestaña o usa F11.');}}
function updateMotion(){document.body.classList.toggle('paused',paused);const b=document.getElementById('motion');b.setAttribute('aria-label',paused?'Reanudar animaciones':'Pausar animaciones');b.title=paused?'Reanudar animaciones':'Pausar animaciones';b.innerHTML=paused?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 11 7-11 7Z"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 5v14M15 5v14"/></svg>';}
prev.addEventListener('click',()=>navigate(current-1));next.addEventListener('click',()=>navigate(current+1));document.getElementById('index-toggle').addEventListener('click',()=>toggleIndex());document.getElementById('close-index').addEventListener('click',()=>toggleIndex(false));document.getElementById('fullscreen').addEventListener('click',fullscreen);document.getElementById('motion').addEventListener('click',()=>{paused=!paused;updateMotion()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-next],[data-slide]');if(!b)return;if(b.hasAttribute('data-next'))navigate(current+1);else{navigate(Number(b.dataset.slide));toggleIndex(false);}});
document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||e.target.matches('input,textarea,select'))return;if(e.key==='Escape'&&indexOpen){toggleIndex(false);return}if(e.key.toLowerCase()==='i'){e.preventDefault();toggleIndex();return}if(e.key.toLowerCase()==='f'){e.preventDefault();fullscreen();return}if(indexOpen)return;if(e.target.closest('button,a')&&[' ','Enter'].includes(e.key))return;if(['ArrowRight','ArrowDown','PageDown',' '].includes(e.key)){e.preventDefault();navigate(current+1)}if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();navigate(current-1)}if(e.key==='Home'){e.preventDefault();navigate(0)}if(e.key==='End'){e.preventDefault();navigate(slides.length-1)}});
window.addEventListener('hashchange',()=>navigate((Number(location.hash.slice(1))||1)-1,false));document.addEventListener('fullscreenchange',()=>{document.getElementById('fullscreen').setAttribute('aria-label',document.fullscreenElement?'Salir de pantalla completa':'Entrar en pantalla completa')});
let touchStart;stage.addEventListener('touchstart',e=>{touchStart=e.touches.length===1?{x:e.touches[0].clientX,y:e.touches[0].clientY}:null},{passive:true});stage.addEventListener('touchend',e=>{if(!touchStart||e.target.closest('button,a,pre'))return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.6)navigate(current+(dx<0?1:-1));touchStart=null},{passive:true});
updateMotion();navigate((Number(location.hash.slice(1))||1)-1);
